<script lang="ts">import {translate,dateLocale} from '$lib/i18n';import {page} from '$app/state';const t=(text:string)=>translate(page.data.lang,text);import {onMount} from 'svelte';import AppHeader from '$lib/AppHeader.svelte';import {Vote,Sparkles,ArrowUpRight,RefreshCw} from 'lucide-svelte';type Poll={id:string;title:string;created:number;closed:number|null;votes:number};let polls=$state<Poll[]>([]),loading=$state(true),message=$state('');async function load(){loading=true;message='';try{const r=await fetch('/api/polls',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.message);polls=d.polls;}catch(e){message=e instanceof Error?e.message:'Your polls could not load.';}finally{loading=false;}}onMount(()=>{load();let timer=setInterval(()=>{if(!document.hidden)load();},10000);return()=>clearInterval(timer);});</script>
<svelte:head><title>{t("My Nail Polls — Rose Atelier")}</title></svelte:head>
<div class="app-shell"><AppHeader/><main class="polls-main"><div class="gallery-heading"><div><span class="eyebrow">{t("A LITTLE GROUP DECISION")}</span><h1>{t("Your looks.")}<br/><i>{t("Their favorites.")}</i></h1><p>{t("Share 2–4 designs from today and let your friends choose. Open a poll to see live results or close voting.")}</p></div><a class="primary" href="/gallery"><Sparkles size={17}/>{t("Create a poll from my gallery")}</a></div>{#if message}<div class="gallery-empty" role="alert"><p>{t(message)}</p><button class="primary" onclick={load}><RefreshCw size={16}/>{t("Try again")}</button></div>{:else if !polls.length}<div class="gallery-empty"><span class="empty-flower"><Vote size={32}/></span><h2>{loading?t("Opening your polls…"):t("Make your next manicure a group decision.")}</h2><p>{t("Choose 2–4 looks made today in your gallery to publish your first poll.")}</p><a class="primary" href="/gallery">{t("Choose 2–4 looks")}</a></div>{:else}<div class="poll-list">{#each polls as poll}<a href={`/p/${poll.id}`}><div class="poll-list-icon"><Vote size={25}/></div><div><span class="eyebrow">{poll.closed?t("CLOSED"):t("LIVE")} · {poll.votes} {t("VOTES")}</span><h2>{poll.title}</h2><p>{new Date(poll.created).toLocaleDateString(dateLocale(page.data.lang))}</p></div><ArrowUpRight size={22}/></a>{/each}</div>{/if}</main></div>
